-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[60671] = { id = 60671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacrifices We Must Make", description = "Hurry! We can use the animacones we gathered to save Derawyn.\n\nI know they're intended for the wildseeds... but we can't let these monsters take anyone else from us.", completion = "The heart of the grove...\n\nWe have to get it back... for all those who have fallen.", objectives = "Use the recovered animacones to save Wagonmaster Derawyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60673] = { id = 60673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor", description = "Right, looks like I should let you in now.\n\nCan't promise Mateo will be too kind though. I prefer my old boss, but don't tell him that.\n\nWonder what happened to her. Denathrius seemed awfully upset when they last spoke.\n\nAnyways, let me just get that door open for ya.", progress = "Do you have Mateo's mirror shard?", completion = "He showed so much promise in his duties.\n\nI suppose the promise of power was too much for him to resist. But now is not the time to dwell on such things, {name}. Let us proceed.", objectives = "Kill Sinkeeper Mateo and collect his mirror shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60709] = { id = 60709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recovering the Heart", description = "Darkness grasps the heart of Droman Krelnor, as he grasps the heart of the grove.\n\nAnima drains from the heart, nectar taken from ripened fruit. It must be stopped.\n\nFoul magic bars the way. Anima in peril, anima the salvation.\n\nBeseech Te'zan. An old soul, brimming with anima, the spark to ignite our hope.", completion = "We've lost so much. Why would anyone do this?", objectives = "Speak with Te'zan to break down the droman's barrier, then confront Droman Krelnor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60721] = { id = 60721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Anima Must Flow", description = "This device you see here can be used to send anima to the thirsting wards, aiding our people.\n\nAs each ward regains its flow of anima, it will begin to flourish. You may find those that live there ready to aid you in your journeys, or you may even find new challenges that await you.\n\nOnce you have brought some anima to our sanctum, use the device to direct it to a ward, and see the results for yourself.", completion = "Anima is flowing to a ward once more. You will want to return to the device periodically and channel more.\n\nAs you gather anima and channel it into Revendreth, the flows will grow stronger. Though they will not last for long right now, eventually you will be able to reinforce the channel, making a permanent connection.\n\nWith anima flowing into our lands once again, it is only a matter of time until we unite all of Revendreth under our banner.", objectives = "Use the Anima Conductor to channel anima to a location in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60722] = { id = 60722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tower Power", description = "This device is used to channel anima to our towers across Maldraxxus, empowering our forces stationed at them.\n\nThough you may find the support they offer useful, bear in mind that the anima will likely attract the attention of our foes.\n\nUse the device to direct our stores of anima toward one of our towers. You will soon see what true power can accomplish.", progress = "The anima must flow!", completion = "Yes, yes! I feel the flow of anima. You will want to return to the device periodically and channel more.\n\nAs you gather and channel more anima to a tower, its connection to our sanctum will grow stronger. Eventually you will be able to reinforce the channel, making it permanent.\n\nWith enough anima flowing throughout Maldraxxus, our armies will be unstoppable!", objectives = "Use the Anima Conductor to channel anima to a location in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60723] = { id = 60723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Roots Thirst", description = "This device can soak the roots of our great canopy in anima. The branches thirst for it.\n\nAs each of the great trunks is filled with anima, it will begin to bloom once more. You may find those under its boughs ready to aid you, or you may find new challenges that await you in the shade.\n\nNow, bring anima to the sanctum, and use the device to direct it out into the weald. Let the blooms flourish once more.", progress = "The leaves shake in anticipation.", completion = "The roots are soaked in anima once more. Return to the device periodically and channel more anima, so that all may drink deeply.\n\nAs you gather anima and channel it, the flows will grow stronger. While they will not last for long right now, eventually you will be able to reinforce the channel, making a permanent connection.\n\nSoon, all will open their blossoms and bloom in full once more.", objectives = "Use the Anima Conductor to channel anima to a location in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60724] = { id = 60724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heartless", description = "So many of my friends have returned to the cycle... all because of those strange masks.\n\nWhy did they take my friends? What was the point of destroying the heart of my grove?\n\nYou have to return to Tirna Vaal and tell Droman Tashmur what happened here. \n\nI'll make my way there eventually. I just... need some time to say goodbye.", completion = "Shadows loom over the weald, harbingers of tragedy to come.\n\nThe river of fate flows swiftly, its currents inexorable. Where they lead... cannot yet be seen.", objectives = "Return to Droman Tashmur in Tirna Vaal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60725] = { id = 60725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Reports", description = "We cannot anticipate where and when the Scourge will strike.\n\nIn order to mount a defense, the Argent Crusade has set up outposts at several key locations. But we have yet to receive word from them.\n\nSeek out my field officers along the southern road. I expect a full report when you return.", progress = "Reinforcements? Thank the Light!", completion = "The situation appears far more dire than we thought...\n\nCommander Throgg must hear of this.", objectives = "Gather reports from officers in Durotar and the Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60727] = { id = 60727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message from Icecrown", description = "Our forces in Northrend have sent word. Justicar Trueheart requests our immediate assistance.\n\nWe must respond to this summons at once, no matter what terrors await us in Icecrown.\n\nA {class} like you would do much to bolster our chances on the battlefield.\n\nYou have my word that Orgrimmar will be protected in your absence.\n\nBattle calls, {name}. I trust you are ready.", completion = "You arrive just in time. Commander Throgg spoke highly of you.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60732] = { id = 60732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Flow", description = "<The tortured embodiment of the soul before you burns with magmatic flame. Whatever purpose it was meant for here in the cauldron has since been served.\n\nThe complete disregard for the remaining husk of this soul is unsettling. These efforts will continue if something isn't done.\n\nSend the inhabitants of Zovaal's Cauldron a message.>", completion = "Rejoice in your accomplishment, but do not forget the weight of your actions.\n\nHe is always watching.", objectives = "Disrupt the Mawsworn's efforts in Zovaal's Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60733] = { id = 60733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Front and Center", progress = "Come! Victory awaits!", completion = "By blood and thunder, we will crush our foes.", objectives = "Empower the Rune of Might at the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60735] = { id = 60735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble in Paradise", description = "I have given your presence here some thought, {name}.\n\nIt is clear to me that you are no ordinary arrival from Oribos. I do not know why you are here, nor what you hope to achieve. That alone is simply unprecedented.\n\nYou must understand... individuals do not merely come to Bastion on a whim. This fate is earned, and those that are chosen for it are uniquely suited to this existence.\n\nSo... I ask you... why are you here, truly?", progress = "<Kalisthene peers down at you.>\n\nWhat is it, mortal?", completion = "<Kalisthene peers down at you.>\n\nWe have heard you, mortal.", objectives = "Answer Kleia's question.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60736] = { id = 60736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest 02", sourceObjective = "Open the door to the Seat of the Primus.", sourceObjectiveStatus = "unverified-source-field" }
quests[60737] = { id = 60737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Door to the Unknown", description = "You empowered the final rune? Then we might yet turn the tide of battle!\n\nOpen the door, {name}! We'll hold the enemy back as long as we can!", completion = "<The runeblade glows brighter as you approach an old stone altar.>", objectives = "Open the door to the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60738] = { id = 60738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way to Hibernal Hollow", description = "I've never seen a wildseed quite like this one. Even the ones that bonded with their caretakers in the past never manifested nightmares like this.\n\nThen again, we've also never had a living mortal in our midst.\n\nWe need to bring this wildseed to Hibernal Hollow. There it can receive the care and attention it needs.\n\nI'll place it into the spirit cradle. Can you ask Niya if she would accompany you?\n\nThe poor sylvar has been directionless since the fall of her grove. This would be good for her.", completion = "I'm surprised that any wildseed could spawn such nightmares.", objectives = "Recruit Niya to help you bring the wildseed to Hibernal Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60739] = { id = 60739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tough Crowd" }
quests[60757] = { id = 60757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skeleton Key", description = "I see Thrall. But... the path to him is sealed.\n\nYou must find the key.\n\nThe task ahead is fraught with peril. You must journey to the Maw, and deliberately invoke the Eye of the Jailer to fall upon you. Tempt fate until his strongest assassins strike.\n\nOne of them will possess the key we need.", objectives = "Go to the Maw, and attract the Eye of the Jailer until you find an Upper Reaches Key on one of the Jailer's assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60759] = { id = 60759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damned Intruders", description = "It is imperative that these reports reach Commander Throgg, but we are hard-pressed to defend the Crossroads.\n\nBefore you depart, I ask that you aid us in thinning the Scourge's numbers. It may grant us the reprieve we need.", progress = "In troubled times, the Light guides our path.", completion = "You have my thanks, {class}. It will take all of our might to vanquish the Scourge.", objectives = "Kill 6 Cultists and 4 Bloodthirsty Ghouls at the Crossroads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60761] = { id = 60761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Scourge", description = "Deliver these reports to Commander Throgg. He must be told of the full extent of the threat we face.\n\nIf we fail to hold the line against the Scourge... then Light help us all.", completion = "I will pass this report onto the Regent Lord. I fear this is only the beginning. \n\nWord has come from Icecrown. The darkness stirs, and your strength is needed.", objectives = "Bring Lieutenant Althera's report to Commander Throgg in the Valley of Strength in Orgrimmar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60762] = { id = 60762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death Motes", description = "I have a task for you, Maw Walker.\n\nSouls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will.\n\nIt is a tragic end.\n\nI wish to better understand this process--what is it about a soul that causes this transformation?\n\nFragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.", completion = "It is perhaps... ethically questionable to benefit from these motes, given their source. \n\nBut such knowledge may prove vital in defeating our enemies.", objectives = "Collect 10 Death Motes from Ruin's Cradle in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60763] = { id = 60763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Moustache You to Lend a Hand", description = "A message from the Primus of Maldraxxus, you say? We haven't heard from him in... Well, it's been a long time.\n\nThis isn't a prank, is it? The Queen doesn't have time for pranks. But I do!\n\n<Moonberry leans in close and whispers to you.>\n\nAnd for this one, I think we need one more lily.\n\n<Moonberry winks.>\n\nLet me take a look at this message. You bring that last night lily to Featherlight, and then we'll talk.", completion = "I hope that your arrival in Ardenweald is a sign that better times are on the horizon.", objectives = "Assist Moonberry and Featherlight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60764] = { id = 60764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soothing Song", description = "I will fly ahead to Hibernal Hollow and convince the Droman Aliothe to help us. Hopefully she will have agreed by the time you and Niya arrive.\n\nThis wildseed seems to take comfort in your presence, so you'll need to stick close to it.\n\nNiya will also need to sing to the wildseed to keep it calm... or else the nightmares may return.\n\nSpriggans love to interrupt our songs, so be on the lookout for them.\n\nLet me know when you're ready to head off.", progress = "How strange that such a small wildseed could cause so much trouble...", completion = "It's good to see you again. The Wild Hunt could use your help.", objectives = "Travel with Niya to take the wildseed to Hibernal Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60765] = { id = 60765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cure For All Ills", description = "Many survivors from the House of Plagues are still in need help. Their suffering fills me with great sadness.\n\nMaw Walker, I'd do anything to help them. Even saving a few is better than saving none.\n\nPlease, help me cure them!", completion = "You and Roseboil have done well to help the survivors from the House of Plagues.", objectives = "Use Roseboil's Regenerative Molt to cure 15 Plague-ridden Survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60766] = { id = 60766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damned Intruders", description = "Before you depart... we are in desperate need of reinforcements.\n\nThese reports must reach Commander Gregor. But if you would help us thin the Scourge's numbers first, it would grant us a much needed reprieve.", progress = "In troubled times, the Light guides our path.", completion = "Thank you, {class}. We will need all the strength we can muster in the coming days.", objectives = "Kill 12 Scourge in the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60767] = { id = 60767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Scourge", description = "Deliver my report to Commander Gregor. He must be informed of what we are up against. \n\nThe Scourge's numbers are on the rise, and if they do not abate... then the Light help us all.", completion = "I will see to it that King Greymane and the Lord Commander receive these reports, though I fear this is only the beginning.\n\nThis courier has just brought us dire news from Icecrown.\n\nIt appears we are not the only ones under assault.", objectives = "Bring Lieutenant Vernon's report to Commander Gregor in the Trade District of Stormwind City.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60770] = { id = 60770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squish and Burn" }
quests[60775] = { id = 60775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Demise", description = "Surviving in this miserable place has been difficult, but I must confess... sending a few Mawsworn to a suitable demise does bring me joy.\n\nThe soulforgers in Zovaal's Cauldron are among the cruelest minions the Jailer employs. I find satisfaction in disposing of their cores in the very forges which they maintain.\n\nThis of course has the added benefit of temporarily slowing down their arms production, if you require more sober justification for your actions.", completion = "Next time, ask me how to run a stampede of mawrats off the edge of a cliff. That never fails to entertain.", objectives = "Throw 5 Soulforged Cores into Soulforges in Zovaal's Cauldron in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60778] = { id = 60778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildseed Rescue", description = "<Featherlight checks his notes.>\n\nLet's see... There was a request for help regarding an imperiled wildseed and... something about an egg? The original note wasn't entirely clear, but the fae who sent it was... Ah! It was Korenth. Again.\n\nWell, I suppose we'll find out what his trouble is soon enough!\n\nI'll fly ahead and look for him. Stick to the path.", progress = "You survived!", completion = "That was fun to watch! You had that bird ready to build a nest and raise hatchlings!\n\nOh, how I needed that laugh...", objectives = "Help Korenth recover the wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60785] = { id = 60785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Crashers!" }
quests[60786] = { id = 60786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swarm Defense" }
quests[60825] = { id = 60825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateur Spies", progress = "Your court is infested with spies, Maw Walker.\n\nNecromancers from Maldraxxus, amateurs hoping to ambush me while my guard is down.\n\nI will dispatch any that I come across, but I would prefer to focus my attentions on the court.\n\nBring me the heads of shrouded necromancers to prove you have some competence in counterintelligence.", completion = "They thought to spy on the Matron of Spies herself?\n\nFools get what they deserve." }
quests[60827] = { id = 60827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing the Effort", description = "While the other crusaders regain control of the tournament grounds, you and I must press on.\n\nOur forces previously attempted to set up a forward camp farther into Icecrown, but they were overrun.\n\nWith you by our side, I am confident we can reclaim the area.", progress = "There is no stopping what has begun. We must continue our efforts.", completion = "Excellent work, {name}. \n\nPreparations are underway. Soon the foothold will be stocked and ready for use as a staging ground.\n\nFor the time being, there are other matters that require your attention.", objectives = "Secure a foothold atop the Ironwall Rampart in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60828] = { id = 60828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Foothold", description = "Our preparations are complete. It is time we take the fight to the Scourge.\n\nJusticar Trueheart has tasked me with leading our efforts at the forward camp.\n\nMeet me there and we shall continue our work together.", completion = "Our scouts report increased activity among the Cult of the Damned.\n\nI believe it is time we learn exactly what our fanatical friends are planning.", objectives = "Meet Crusader Renn at the Argent Camp atop the Ironwall Rampart in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60831] = { id = 60831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fit For a Margrave", description = "We're finally ready, my apprentice. We shall craft our greatest potion!\n\nThough what the potion is meant for escapes me, I'm simply so proud of your progress. Margrave Stradama will be thrilled by your achievements!\n\nCome, now. Let's present what we've made to her!", progress = "Go on, apprentice!", completion = "Ah... apprentice? Are you there? I feel... strange.", objectives = "Present your potion to Margrave Stradama.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60837] = { id = 60837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of Aliothe" }
quests[60839] = { id = 60839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the Wild Hunt", description = "The Wild Hunt is holding the line against these monsters, lest they overrun the road to Hibernal Hollow.\n\nToo many of my fellow hunters have been possessed by the dark magic of those twisted masks.\n\nBut with you here, we might be able to turn the tide. \n\nAid any hunters you can find before our foes turn them against us.\n\nI will meet you farther within the meadow. If we rally our numbers, we can bring an end to this battle.", completion = "Thank you for rescuing my fellow hunters. We'll have time to respect those who have returned to the cycle when this is all over.", objectives = "Rescue 5 Wounded Defenders from Soryn's Meadow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60840] = { id = 60840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Hunt Offensive" }
quests[60841] = { id = 60841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuation Effort", description = "Our forces are in danger, and the fault is my own. Believing that the surrounding area was safe, I sent a small team to secure the abandoned camp in the valley to the southwest.\n\nBut our field reports were outdated or mistaken. The camp is a lost cause. We must now focus on rescuing those whom I assigned to it.\n\nHead for the camp. Do what you can to save our allies.", completion = "Thank you, {name}. Your efforts have saved many lives.\n\nFrom here on out, I will ensure that our scouting reports are accurate and up to date. It seems the threats we face escalate with each passing day.", objectives = "Rescue 6 allies in the Valley of Lost Hope. Kill 6 Scourge in the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60842] = { id = 60842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Serve Spriggan" }
quests[60843] = { id = 60843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cult Couture", description = "Though our scouts have been able to infiltrate the cultist forces at Aldur'thar, sneaking into Mord'rethar has proven all but impossible.\n\nPerhaps it is time to explore other methods of ingress.\n\nStart by investigating the cult's nearby ritual chambers. You may find something of use.", progress = "Find something?", completion = "These should suffice.", objectives = "Collect a Collaborator's Hood and a Collaborator's Robe from the cultists at Aldur'thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60844] = { id = 60844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight School: Falling With Style" }
quests[60855] = { id = 60855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormageddon" }
quests[60856] = { id = 60856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toppling the Brute", description = "A nearby monstrosity has been thwarting our efforts to clear the meadow.\n\nTogether, we can bring it down.\n\nYou and I will face off against the beast. When the time is right, I will call for the hunt to charge.\n\nThe Wild Hunt has suffered too many losses. Today we will claim victory against these monsters!", completion = "Fine work, {name}. This won't win our war... but it will at least help us in the fight for Soryn's Meadow.", objectives = "Defeat the Blighted Beast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60857] = { id = 60857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can't Save Them All", description = "I am surprised--but pleased--that you weren't torn to pieces! Well done.\n\nBut now... I fear we have a far more serious task to complete.\n\nThe Winter Queen has decreed that Heartwood Grove's anima is to be reclaimed, and its denizens must leave it to wither. Not all of their wildseeds will go with them. In fact, only a few have been chosen to be saved.\n\nWe are to bring the final list to Droman Krelnor.", progress = "Move along, stranger.", completion = "<Droman Krelnor sighs wearily as he reads the short list of wildseeds.>\n\nAt least a few will be relocated to Tirna Vaal.", objectives = "Bring the list of saved wildseeds to Droman Krelnor at the Heartwood Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60858] = { id = 60858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight School: Up and Away!" }
quests[60859] = { id = 60859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souls of the Forest", description = "If you're standing in for Lady Moonberry, then maybe you can help!\n\nWagonmaster Derawyn was escorting a bunch of us to a new grove when we were attacked by a pack of hungry predators! The wolf be a fast soulshape, so I got away... but some of the little ones weren't so lucky. They're being hunted like prey!\n\nCome on! They're just down the road!", progress = "Well, that was exciting.", completion = "It's been a while since a new soul arrived in Ardenweald, so each one already here is precious to us.\n\nI'll be sure to let Lady Moonberry know of your heroic rescue efforts on her behalf. She might even decide she owes you a favor!", objectives = "Rescue souls in peril.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60861] = { id = 60861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in Shadows", description = "Though we have been monitoring the cultist presence at Mord'rethar, we have not yet discovered what mysteries lie within its chambers.\n\nTake these robes. Make your way into the inner sanctum and see what you can discover.\n\nThis may be our only chance to learn their intentions, {name}.", progress = "Find something?", completion = "<This news is rather unsettling.>", objectives = "Use the Collaborator's Robes in Mord'rethar to discover what secrets lie within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60867] = { id = 60867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message from Above", progress = "The skies over the citadel may be dangerous, but we need to know what we're up against.", completion = "With their numbers momentarily reduced, now is our chance to strike.", objectives = "Discover the location of Herald Dalora. Destroy the Scourge forces surrounding Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60869] = { id = 60869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Hope in Hand", description = "You must bring word of what we have uncovered back to Orgrimmar. One of our mages can open a portal for you at the tournament grounds.\n\nAs for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use.\n\nMay the Light protect you, {name}.", completion = "This is troubling news, {name}. To think that Sylvanas would willingly ally with such a dark power...", objectives = "Establish a portal to Orgrimmar at the Argent Tournament Grounds. Deliver the news to Lor'themar Theron atop Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60871] = { id = 60871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Hope in Hand", description = "You must bring word of what we have uncovered back to Stormwind. One of our mages can open a portal for you at the tournament grounds.\n\nAs for the Argent Crusade, we must remain a bulwark against the Scourge. If you wish to continue aiding us, I will see to it that your skills are put to good use.\n\nMay the Light protect you, {name}.", completion = "These are grim tidings, {name}. It seems the Banshee has aligned herself with a darker power than we know.", objectives = "Establish a portal to Stormwind at the Argent Tournament Grounds. Deliver the news to Genn Greymane at Lion's Rest in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60872] = { id = 60872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dangerous Harvest" }
quests[60881] = { id = 60881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride of the Wild Hunt", description = "Thanks to your efforts, we have turned the tide of battle. We won't soon forget your aid. \n\nWe should be able to hold Soryn's Meadow, now that this brute is dead. \n\nRide with us, {name}. Let us return to the road and your wildseed.", completion = "It is good to see part of the Wild Hunt's strength restored... and also that you found the spirit cradle of use.\n\nNow let us bring the wildseed within it to Hibernal Hollow.", objectives = "Ride with the Wild Hunt to Niya and the wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60886] = { id = 60886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seat of the Primus", description = "This cannot be a coincidence. It is clear that your runeblade is somehow connected to the Seat of the Primus.\n\nI will not pretend to know the Primus's agenda. But I would not be surprised if he left behind a way for the worthy to open the door to his sanctum.\n\nDraka will bring you to the Seat of the Primus. If you hold the key, mortal, then our victory is all but assured.", progress = "What is it?", completion = "We cannot lose sight of the battles ahead of us. The door will have to wait.", objectives = "Go with Draka to the Seat of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60887] = { id = 60887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm: Onward to Adventure in Kalimdor", description = "There are people across Azeroth that could use your help, {name}. They come from different walks of life, but are all working towards finding their place on this beautiful world.\n\nExamine the Warchief's Command Board and see where your adventure awaits!", progress = "I cannot wait to hear your stories someday.", completion = "So many choices, so little time!\n\nGood luck out there, {name}... but I don't think you'll need it.", objectives = "Find the Warchief's Command Board in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60889] = { id = 60889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favor: She Had a Stone Heart", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", completion = "Is that a piece of paper?\n\n<You present Ta'xera with the poem.>\n\nA Stoneborn poem! Very few stoneborn express feelings or desires beyond that of the service and loyalty chiseled into them. \n\nI shall enjoy, I mean, this will make excellent documentation of potential depth to the Stoneborn, you must let me buy it!", objectives = "Bring the She Had a Stone Hearth poem to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60891] = { id = 60891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm: Onward to Adventure in the Eastern Kingdoms", description = "There are people across Azeroth that could use your help, {name}. They come from different walks of life, but are all working towards finding their place on this beautiful world.\n\nExamine the Hero's Call Board and see where your adventure awaits!", progress = "I cannot wait to hear your stories someday.", completion = "So many choices, so little time!\n\nGood luck out there, {name}... but I don't think you'll need it.", objectives = "Find the Hero's Call Board in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60898] = { id = 60898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Ara'lon", description = "{name}, I have an urgent request to make of you.\n\nRecently, the Wild Hunt has been encountering the masked fae in greater numbers... particularly in the area surrounding Blackthorn Grove. I sent a hunting party to investigate, but they have yet to return.\n\nAra'lon was leading the hunt. You have offered him aid before, yes? I ask that you do so again.\n\nSearch the area for signs of the missing hunters and report back to me.", completion = "Keep your voice down. There are masked fae are nearby...", objectives = "Search near Blackthorn Grove for Ara'lon and the lost hunting party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60899] = { id = 60899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Night in the Woods" }
quests[60900] = { id = 60900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archival Protection", description = "The rarest volumes are kept at the top of this tower, protected by an entity called the Archivist.\n\nThis stoic guardian is incorruptible. Intractable. Completely uninterested in striking a fair bargain!\n\nIts utter lack of business acumen is really quite upsetting.\n\nAh, well. I fear we have no choice but to dispatch this impediment. Shall we?", completion = "The volumes are not here!\n\nThe Archivist's final words must have meant something. A clue, perhaps?", objectives = "Defeat the Archivist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60901] = { id = 60901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passage to Hibernal Hollow", description = "You have done the Wild Hunt a great service. I must repay you in some way.\n\nThe battle for Soryn's Meadow has turned. With the brute defeated, the Blighted forces lose their strength.\n\nAllow us to escort you to Hibernal Hollow.\n\nSpeak to me whenever you wish to depart.", completion = "Dreamweaver has told me much about your strange wildseed. \n\nI will do what I can to help.", objectives = "Speak with Ara'lon to receive an escort to Hibernal Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60903] = { id = 60903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krala" }
quests[60904] = { id = 60904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medallion of Desire", description = "The Medallion of Desire rests upon the neck of the Countess. \n\nIt is a source of power for her, but not her only source of power. Claiming it by force would merit us only a short victory. For this we must be much more subtle.\n\nLucky for us, Theotar has come to me with a plan but he will need your help. Speak with him and see what the two of you can do. \n\nHe was closer to the Countess than any of us for a long time and I would consider him our resident expert on her.", completion = "Down for a little espionage and intrigue?", objectives = "Speak with Theotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60905] = { id = 60905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infusing the Wildseed", description = "Dreamweaver tells me of a ritual to quell the wildseed's nightmares... but it will require anima.\n\nA soul named Proglo lives beneath this tree, gathering anima for the grove's caretakers to use.\n\nHis mortal life came to a violent end, and his soul has been skittish ever since. He will not respond well to your current form.\n\nI will grant you the ability to assume the soulshape of a fox. Approach Proglo in your new form to gain his trust and ask for his anima.", progress = "I hope we can aid this wildseed.", completion = "It's going to be difficult, but I know of a place where there may be enough anima to help this wildseed.", objectives = "Use Soulshape to collect anima from Proglo, then infuse the wildseed with the collected anima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60906] = { id = 60906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rightful Resting Place", description = "You have truly proven yourself a hero in the eyes of those who are its absolute judge.\n\nI thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place.\n\nLet us meet at Hero's Rest where you can do the honors.", progress = "<The resting place of the spear lies before you.>", completion = "<Place the Spear of Kalliope in its rightful place knowing that only a true hero can do so.>", objectives = "Enshrine the Spear of Kalliope in its rightful place at Hero's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60907] = { id = 60907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascension Calling: Kleia", description = "<This scroll details an invitation for Kleia to join you and Pelagos on the Path of Ascension.\n\nIt would be wise to deliver this to her at once.>", completion = "Time to stretch my wings!", objectives = "Inform Kleia she is now able to participate in the Path of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60910] = { id = 60910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masks of Deception", description = "My hunting party was ambushed not far from here. I narrowly escaped capture, but the others were taken deeper into Blackthorn Grove.\n\nWe must find and rescue them, but we are vastly outnumbered. We'll need to disguise ourselves while we search the grove.\n\nSee if you can find something we can use to do so. I need just a little longer to recover from my wounds.", progress = "What have you found?", completion = "Yes! We can use these masks to disguise ourselves.", objectives = "Find two Masks of Possession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60911] = { id = 60911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight School: Flapping Frenzy" }
quests[60916] = { id = 60916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Stonehead", description = "Hi, best bud!\n\nMe no go party. \n\n<Stonehead shakes his head vigorously.>\n\nGot to stay for job!", progress = "Hi, best bud!", completion = "<Stonehead scratches his head and peers at the document.>\n\nMe see lots of wax blobs.\n\n<Stonehead thinks very hard, moving his lips as he tries to sound out words.>\n\nUmm... maybe... it... say... Me go party with best bud?\n\nYay! Me go party with best bud!", objectives = "Forge a document to give Stonehead permission to leave his post for the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60920] = { id = 60920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akros" }
quests[60928] = { id = 60928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackthorn Captives", description = "These disguises will allow us to explore the grove undetected, but beware of the overseers. Their Drust magic will more than likely be able to pierce through our deception.\n\nWe need to save the rest of my hunting party while we still can.", progress = "The Drust have taken so much from us...", completion = "Gweyir is the only survivor... but she's already been afflicted by the Drust's cursed magic. \n\nWe can't just leave her here. Not like this!", objectives = "Locate the missing hunters in Blackthorn Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60929] = { id = 60929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Air Supremacy" }
quests[60930] = { id = 60930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower Your Standards", progress = "<Picky Stefan leans in close and whispers.>\n\nMaw Walker, we are running low on refreshments!\n\nThankfully, you chose to serve such a humble... \"delicacy\"  that we can find more just about anywhere.\n\nAs you find fungus around the Ember Court, bring them to me and I shall have the dredgers sneak it onto the empty platters.", completion = "Normally, I would be far more discerning in what we serve our guests, but this crowd seems to lack my sophisticated palette." }
quests[60932] = { id = 60932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only Shadows Remain", progress = "May we continue our fight together.", completion = "It seems that eliminating the herald has slowed the Scourge's advance.\n\nWe will have to remain vigilant. Thank you for all you have done, {name}.", objectives = "Defeat Herald Dalora in the Cathedral of Darkness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60934] = { id = 60934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Lord Herne", description = "I will do whatever it takes to save Gweyir from the Drust's curse.\n\nLord Herne must be informed of what befell my hunting party. Deliver my report to him while I escort Gweyir back to the Heart of the Forest.\n\nGweyir was under my leadership during the ambush... she is my responsibility. I will make sure she gets home safely.", progress = "Did you find the lost hunting party?", completion = "So Gweyir and Ara'lon are the only survivors... this is grave news.", objectives = "Deliver Ara'lon's report to Lord Herne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60935] = { id = 60935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medallion of Avarice", description = "The Medallion of Avarice was the tool of the Curator.\n\nWith its power it granted her authority over the Catacombs Ward. Combined with her knowledge of the vast library of sinstones Revendreth has accumulated over the ages, the Curator was a master of her craft.\n\nWhen Denathrius defeated my first rebellion, he tossed both myself and the Curator into the Maw. \n\nThe Curator was clever, though, and she hid the medallion before Denathrius could act. Come, let us speak of plans.", completion = "The Curator is one of the few remaining true venthyr forged during the founding of Revendreth.\n\nHer memory is vast, but her time in the Maw has fragmented the order of those memories.\n\nShe will need your help.", objectives = "Speak with Prince Renathal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60945] = { id = 60945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Echo Trident", description = "<The trident glistens in the sunlight.\n\nThis should give your soulbinds the ability to interrupt their foes in the Path of Ascension.>", completion = "Trident? Very very nice! I hold on for safe keeping.", objectives = "Bring the Deep Echo Trident to Paolone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60946] = { id = 60946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Deep Echo Trident", description = "<You have discovered plans for a trident that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Deep Echo Trident to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60947] = { id = 60947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Charm of Fortitude", description = "<You have discovered plans for a charm that seems to fortify your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Charm of Fortitude to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60948] = { id = 60948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: The Countess", description = "The Prince wishes to host court? Well, that should be interesting...\n\nI am sure you understand that one musn't give without receiving something of value in return. It sets a terrible precedent, provides unrealistic expectations, and encourages beggars. \n\nSo you shall do something for me.\n\nHouse Briarbane is very proud of their new mascot. They have been flaunting it in the streets and irritating the other houses.\n\nSteal it for me, but incriminate one of the other houses in the act.", progress = "It would be a shame to waste such a fine mascot on such an unworthy house.", completion = "Lovely. That should keep the houses distracted while I attend the Prince's soiree.", objectives = "Disguise yourself as a member of House Iremoore and steal the House Briarbane mascot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60950] = { id = 60950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Matter of Stealth" }
quests[60955] = { id = 60955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noko's Flute", progress = "<Noko breathes in slowly.>\n\nThe stage manager says he cannot find my flute anywhere.\n\nThe last time this happened, one of the rowdy roadies had run off with it.\n\nYou can find those troublesome dredgers causing trouble around the party.\n\nRetrieve my flute from them and I will play for your guests.", completion = "<Noko holds his flute tenderly.>\n\nI only truly feel like myself while holding the flute of my caravan.\n\nThank you for providing the opportunity to play." }
quests[60957] = { id = 60957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansel's Lucky Violin", progress = "<Lucky Ansel reluctantly breaks gaze with his sinstone.>\n\nMy burdens are still far too heavy.\n\nI will never be free of the Maw's dangers while even a single sin remains on this stone.\n\nLuckily, my exceptional music warrants praise from my venthyr controllers, and I am assured that aiding Prince Renathal's court is a worthwhile endeavor.\n\nRetrieve my violin from the band supplies over near the dancers and I will begin my public penance.", completion = "<Ansel turns his violin as it sparkles in the light.>\n\nLet the show begin." }
quests[60958] = { id = 60958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Send Only You" }
quests[60959] = { id = 60959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Onward to Adventure in Outland", description = "The harsh remains of Outland will test the strength of even the hardiest adventurers like yourself.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the shattered world of Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60960] = { id = 60960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiu's Lute", progress = "I am nervous, {name}. Music lays bare my soul for all to see.\n\nAnd while this sinstone reminds all of the darkness within me, I hope that my music will expose the light that also dwells within.\n\nLord Garridan at your embassy agreed. He as most kind and enjoyed the music I played for him when I first arrived.\n\nI must've left my lute with him. Please retrieve it for me while I continue my pre-show meditation.", completion = "<Chiu speaks to the lute while she quickly tunes its strings.>\n\nWhat did those dredgers do to you, old friend?" }
quests[60961] = { id = 60961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: Onward to Adventure in Outland", description = "The harsh remains of Outland will test the strength of even the hardiest adventurers like yourself.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the shattered world of Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60962] = { id = 60962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Onward to Adventure in Northrend", description = "The Lich King will stop at nothing to subjugate every living being on Azeroth.\n\nFind your way back to Northrend and continue your adventure!", objectives = "Travel to the icy continent of Northrend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60963] = { id = 60963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Onward to Adventure in Northrend", description = "The Lich King will stop at nothing to subjugate every living being on Azeroth.\n\nFind your way back to Northrend and continue your adventure!", objectives = "Travel to the icy continent of Northrend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60964] = { id = 60964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: Onward to Adventure in Pandaria", description = "There are mysteries to uncover and secrets to discover out in the lush lands of Pandaria, {name}.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the mysterious land of Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60965] = { id = 60965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: Onward to Adventure in Pandaria", description = "There are mysteries to uncover and secrets to discover out in the lush lands of Pandaria, {name}.\n\nFind your way back there and continue your adventure!", objectives = "Travel to the mysterious land of Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60968] = { id = 60968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: Onward to Adventure in Draenor", description = "You mustn't delay, {name}. The people of Draenor still need your help!\n\nFind your way back there and continue your adventure!", objectives = "Travel to the orcish homeworld of Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60969] = { id = 60969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: Onward to Adventure in Draenor", description = "You mustn't delay, {name}. The people of Draenor still need your help!\n\nFind your way back there and continue your adventure!", objectives = "Travel to the orcish homeworld of Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60970] = { id = 60970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: Onward to Adventure in the Broken Isles", description = "The Burning Legion's infinite army marches on our world, threatening to destroy Azeroth and everyone on it!\n\nFind your way back to the Broken Isles and continue your adventure!", objectives = "Travel to the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60971] = { id = 60971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion: Onward to Adventure in the Broken Isles", description = "The Burning Legion's infinite army marches on our world, threatening to destroy Azeroth and everyone on it!\n\nFind your way back to the Broken Isles and continue your adventure!", objectives = "Travel to the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60972] = { id = 60972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt for the Baron", description = "<The amulet Bolvar gave you flickers with a faint red light, then grows dim.\n\nTo be useful in finding Darion Mograine, you must find a way to restore its potency.\n\nYou recall an area called Zovaal's Cauldron that was teeming with dark magic.\n\nPerhaps the amulet's power could be restored there.>", objectives = "Charge the Amulet of the Horsemen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60973] = { id = 60973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Phial of Serenity", description = "<You have discovered plans for a phial that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Phial of Serenity to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60974] = { id = 60974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phial of Serenity", description = "<Your steward friend gave you an extra bottle to store this potion in.\n\nThis should keep your soulbinds fighting in the Path of Ascension, as your phial does.>", completion = "Phial? Very nice! Just like friend! I hold on for safe keeping.", objectives = "Bring the Phial of Serenity to Paolone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60975] = { id = 60975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Spiritforged Aegis", description = "<You have discovered plans for a shield that may give your soulbinds an edge in the Path of Ascension.\n\nDactylis should be able to help you with crafting this piece of equipment.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Spiritforged Aegis to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60990] = { id = 60990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[60991] = { id = 60991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orrholyn, Lord of Bloodletting" }
quests[60992] = { id = 60992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razkazzar, Lord of Axes" }
quests[60993] = { id = 60993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Citadel of Loyalty", description = "The medallions, the source of magic the crown focuses, are still bent to the will of Denathrius. \n\nForge cannot solve this. Citadel of Loyalty can.\n\nTaken over by the Forsworn in recent times. If we can get the crown to the temple, we can break the loyalty to the medallion's former master.", completion = "Here we are. I'm glad we have your friends here too.\n\nWe are going to need it if we hope to reach the temple.", objectives = "Meet Mikanikos at the Citadel of Loyalty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60994] = { id = 60994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lowering Their Defenses", description = "We can alter the crown to expunge Denathrius's corruption in the medallions.\n\nProblem, Forsworn have set large barrier protecting the temple. Only there can Denathrius's influence be truly broken.\n\nDrain the anima from the barrier's sources that power it. Barrier will disappear.", completion = "Excellent work. \n\nBarrier around the temple is gone. To fix the crown, we must go there.", objectives = "Drain the anima from the Forsworn Barrier Sources.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60995] = { id = 60995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disloyalty", description = "There are many enemies of Bastion here. \n\nIf we thin their numbers, it will further mend the tension between our realms. \n\nShow no remorse. \n\nI will take to the skies to support from above. I will be able to provide ground support when needed.", completion = "Forsworn defeated? Good. The fewer of them there are, the happier I am.", objectives = "Kill 15 Forsworn in the Citadel of Loyalty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[60996] = { id = 60996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Face Your Fears", description = "The temple is now accessible. We must go now to aid Mikanikos in breaking the Sire's influence on the crown.\n\nPrepare yourself. Denathrius's magic has always been potent and destructive. \n\nThis won't be easy.", completion = "With the echo of Denathrius defeated, Mikanikos assures me the crown is pure.\n\nThis is a key victory for Revendreth and all the Shadowlands.", objectives = "Speak to General Draven to go to the Temple of Loyalty. Then, aid Mikanikos in purifying the Crown of the Harvesters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61050] = { id = 61050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Wear Seven Medallions", description = "One venthyr cannot wear seven medallions and command the power they bestow, nor command respect from anyone looking at them.\n\nWhat I propose is the crafting of an artifact that can contain the power of the medallions. Focusing that power to one wielder.\n\nUnfortunately, Revendreth lacks the craftsmanship needed to channel such powers. Not without turning the wearer into a puppet of Denathrius.\n\nNo, for this, we must employ the aid of a realm that specializes in service.\n\nDraven has the details.", completion = "After much strategizing, the Prince and I have developed a plan that requires the aid and resources of someone I once led actions against on behalf of the Master.\n\nPrepare to shield your eyes. We need to go to Bastion.", objectives = "Speak with General Draven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61051] = { id = 61051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent-Minded Artisan", description = "Of all the foolhardy, misguided, exasperating...\n\n<Guardian Kota snorts and stomps a hoof.>\n\nBut standing here does Sha'lor no good. We must find him and bring him back safely.\n\nCome, meet me at the Autumnal Rise. We can survey the burrows below and see if there is any sign that he lives.", completion = "No!\n\nWhatever that beast was, it's taken Sha'lor!", objectives = "Search for Master Sha'lor on the Autumnal Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61057] = { id = 61057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Trials Forged", description = "You have shown strength, cunning and compassion since your arrival in Ardenweald. These are the values the greatest hunters possess. \n\nIt has been a privilege to fight by your side, {name}. It would be my honor to continue, as your Soulbind.", progress = "Together we are stronger!", completion = "Together, we will guard Ardenweald.", objectives = "Complete the soulbinding ritual with Korayn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61058] = { id = 61058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound in Dreams", description = "I knew you were something special when Ysera's wildseed reacted to you. Without you, she would have been lost! It would have been a tragedy not just for Ardenweald, but your world as well!\n\nSince then, I have seen you take on many more tasks to help others in need. With your help, Ardenweald grows stronger.\n\nI would be honored to help you continue the good work you have been doing, and to become your soulbind.", progress = "I am humbled by the care you have shown for others.", completion = "I just know that together we can save Ardenweald and all the spirits who slumber here.", objectives = "Complete the soulbinding ritual with Dreamweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61059] = { id = 61059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Rendle and Cudgelface", description = "I heard about the prince wanting Rendle and me at 'is court. I aim to please 'im an all, but Rendle says 'e  haven't got proper ah-tire.\n\nSays 'e needs a sootible hat, maybe somethin' posh that hints at 'is inner depths.\n\nHe says the only good hats are: Red Noggin Candle, or one a them Fae Revel Masques. Or mebbe a Pink Party Hat, or a fancy Crown o' the Righteous.", completion = "Wot a hat! Rendle will be the talk of the court, 'e will.", objectives = "\"Sootible\" hats may be crafted by players who have the recipe and appropriate tradeskill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61060] = { id = 61060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spore Losers" }
quests[61061] = { id = 61061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulfar's Guidance", description = "There is one who may know how to dispel the curse from Gweyir.\n\nIn the mountains of Drustvar lives Ulfar, an ancient Thornspeaker who sided with the humans of Kul Tiras against his fellow Drust.\n\nJourney to his den and ask for his wisdom. He may hold the answers you seek.\n\nLord Herne and I will tend to Gweyir once she arrives with Ara'lon.", completion = "You have come from beyond the veil to seek my wisdom? A long journey indeed...", objectives = "Speak with Ulfar at Ulfar's Den in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61062] = { id = 61062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adjutant Dekaris" }
quests[61075] = { id = 61075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spark of Light", description = "Gorgoa is a protean force fueled by souls that trickle in from many worlds. They wash in from the head of the river, a place they have named the Crucible of the Damned.\n\nThe Jailer's unblinking eyes patrol the river and watch for souls who attempt escape.\n\nBlind the eyes that find them. Close them for good. \n\nTake this and do what must be done.", progress = "Have you closed the Jailer's eyes?", completion = "Well done, Maw Walker. The Jailer's eyes are dangerous, indeed.", objectives = "Defeat 4 Eyes of Damnation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61076] = { id = 61076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Flame", description = "I know the curse of which you speak. Dark magic that possesses the mind of the afflicted.\n\nLong ago, the Drust were ruled by a sorcerer king named Gorak Tul. It was he who twisted our rituals and set us on the path of death and domination.\n\nYou will need to claim a portion of his power to break the curse. \n\nTake this fetish to Gol Inath and temper it in the Flame of Oblivion. But beware... it is a vile place, and danger lurks among its shadows.", progress = "Gorak Tul's magic empowers the curse, and only his magic can break it.", completion = "I can sense Gorak Tul's dark power seething within this fetish. Handle it with caution, {class}.", objectives = "Imbue the Drust Fetish with the power of Gorak Tul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61077] = { id = 61077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Confronting Sin", description = "Thanks to the raid launched against Castle Nathria, we have obtained an opportunity.\n\nA soul, powerful and fused with dark purpose at the hands of the Master's experiments. \n\nGiven this soul is from Azeroth, the Accuser has asked for your assistance in untwining the corruption done to his sinstone.\n\nthe Accuser awaits you in the lower levels of Sinfall.", completion = "I make no presumption that all mortals from Azeroth know each other. \n\nWhen confronting a challenging soul like this, however, it helps to offer even the faintest of familiarity.", objectives = "Speak with the Accuser in Sinfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61079] = { id = 61079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jailer's Share", description = "The Mawsworn's torturers have a talent for misery.\n\nThe suffering they inflict often produces more stygia than they can collect. The excess floats loosely in the air, left to drift into the abyss.\n\nI have fashioned a conduit specifically for capturing the leftover stygia. You can borrow it if you wish.\n\nThere are a handful of prime gathering locations throughout Calcis. As you'll be using my conduits, we can split what you find upon your return.", progress = "Were the conduits effective? How much stygia did they collect?", completion = "It is satisfying to know that the Jailer's share now belongs to us. Well done, Maw Walker.", objectives = "Place 4 Stygia Conduits at marked locations within Calcis in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61087] = { id = 61087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delayed Delivery: Old Gate Parcel" }
quests[61088] = { id = 61088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust to Dust", description = "The Mawsworn never cease to invent new forms of suffering.\n\nEven the ground on which we tread is formed from souls pounded into dust. With the flood of souls passing through Gorgoa, the Mawsworn are keen to expand their domain.\n\nAt present, the Mawsworn are burying souls and crafting new terrain from their torment. It is not too late for some of them.\n\nFree the buried souls and stop the endless expansion of suffering.", progress = "They are safe?", completion = "The curious forms of torment the Mawsworn invent will never cease to amaze me.", objectives = "Rescue 8 Half-Buried Souls in Calcis in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61092] = { id = 61092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Grandmaster Vole", description = "I'm busy, so I'll get right to the point. \n\nThe only way I'm going is if you pay me enough coin to make it worth my while or you amuse me. \n\nAs interesting and enjoyable as the Ember Court may be, I lose money every time I am away from here. That said, I do love a good slaughter.\n\nSo, coin or deaths. Take your pick.", progress = "You need to cough up the coin or get killing.", completion = "That works. I'll be there. It will be a nice vacation.", objectives = "Convince Grandmaster Vole by bribing him or slaying players of the opposite faction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61095] = { id = 61095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from The Undying Army", description = "Your efforts meet with the approval of The Undying Army.\n\nThese rewards are in recognition of those efforts. May they help you in the battles to come.", completion = "The Undying Army would like to thank you for your efforts in aiding Maldraxxus.\n\nPlease accept a gift in recognition of your service to our cause and our forces.", objectives = "Speak with Nalcorn Talsen at the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61096] = { id = 61096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arbiter's Will", description = "We will all suffer if Bastion and Maldraxxus fall into war.\n\nFor some time, the Necrolords have been isolated. You must travel to their realm and seek the truth of their incursion.\n\nThough our anima reserves remain low, they will be enough to open the way for you.", completion = "This slot shall suffice.", objectives = "Meet Kah-Sher in the Ring of Transference in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61097] = { id = 61097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from The Ascended", description = "The Ascended would like to thank you for your efforts in aiding Bastion.\n\nPlease accept a gift in recognition of your service to our cause and our people.", completion = "The Ascended would like to thank you for your efforts in aiding Bastion.\n\nPlease accept a gift in recognition of your service to our cause and our people.", objectives = "Speak with Adjutant Nikos in Hero's Rest in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61098] = { id = 61098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from The Wild Hunt", description = "The Wild Hunt thanks you for your efforts in aiding Ardenweald.\n\nTake these gifts as recognition for your aid. May they help you in whatever trials may come.", completion = "The Wild Hunt thanks you for your efforts in aiding Ardenweald.\n\nTake these gifts as recognition for your aid. May they help you in whatever trials may come.", objectives = "Speak with Aithlyn at the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61099] = { id = 61099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Baine", description = "I dare not step inside that accursed tower myself, of course.\n\nWhile I cannot tell you exactly where your comrade is being held, I offer a gift to assist you.\n\nUse it inside Torghast. It should take you somewhere near your missing ally. Baine Bloodhoof was his name, yes?\n\nEither that, or you'll end up trapped within the tower's ever-shifting halls for all eternity.\n\nBut those are the risks one must take, I suppose. Best of luck!", progress = "You've found him!", completion = "Finding Baine was no easy feat. But you braved the horrors of that tower and succeeded.\n\nWell done.\n\nBut I fear your work is only just beginning.", objectives = "Enter Torghast and search for Baine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61100] = { id = 61100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from the Court of Harvesters", description = "Your assistance to our cause has not gone unnoticed. More and more venthyr across the realm bind themselves to the Court of Harvesters instead of the Master. \n\nAs a result, we have collection of resources you may find useful, plundered from Sire Denathrius' most devoted followers. They are waiting for you with me in Darkhaven.", completion = "Your assistance to our cause has not gone unnoticed. More and more venthyr across the realm bind themselves to the Court of Harvesters instead of the Master. \n\nPlease accept these token of gratitude.", objectives = "Speak with Mistress Mihaela for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61102] = { id = 61102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kivarr the Thornspeaker", description = "In my youth, I was mentored by a wise and powerful Thornspeaker named Kivarr. She passed from this world long ago, but her soul may yet rest within the Shadowlands.\n\nKivarr's knowledge is ancient and vast, far eclipsing my own. She may be able to offer you the guidance that I cannot.\n\nSeek her out. Deliver the fetish to her. She will know what to do.\n\nMay the wind be your guide.", completion = "Kivarr... yes, I have heard of someone by that name. Ara'lon may know where to find her.", objectives = "Speak with Lord Herne at Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61103] = { id = 61103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Cycle", description = "The shacklers in the Tremaculum are an awful sort.\n\nSouls are tortured there until they turn malevolent. They are then outfitted as guards so the cycle can continue. \n\nIf you wish to slow the rate at which the Jailer raises his armies, start at the source. \n\nDisrupt the cycle at the Tremaculum.", completion = "Well done, Maw Walker. The Jailer's forces are vast, but they are not infinite.", objectives = "Defeat 4 Mawsworn Shacklers and 6 Deadeyes at the Tremaculum in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61104] = { id = 61104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grathalax, the Extractor", description = "There are many powerful lieutenants among the Mawsworn, but there is one who is particularly important to the Jailer.\n\nFar beneath the Tremaculum lives the Jailer's prime interrogator, Grathalax. Power is fed to him via conduits throughout the area.\n\nHis role is to make the process of anima extraction more efficient. His methods are... unkind.\n\nI believe we would both benefit from the end of his existence.", completion = "The end of Grathalax will deal a great blow to the Jailer's infrastructure. Well done.", objectives = "Defeat Grathalax underneath the Tremaculum in The Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61105] = { id = 61105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Plague Deviser Marileth", description = "Oh! This sounds like a wonderful opportunity to do field research in Revendreth, apprentice.\n\nI look forward to collaborating with new colleagues. We must bring a gift to thank them for their invitation. What could be more appropriate than some lovely slimes?\n\nPlease pick some of the best slimes for me to present to our host. Just bring them to Kevin so they can make friends and travel together.", progress = "Have you finished choosing our gift slimes yet, apprentice?", completion = "You've done very well apprentice!", objectives = "Herd Bubbling Oozes to Kevin so Plague Deviser Marileth has a present to bring to the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61107] = { id = 61107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Land of Strife", description = "It is imperative that you identify the cause of the attack on Bastion.\n\nWe will require your aid to open the gateway. Once the focus is sufficiently powered, we will call upon the gate to Maldraxxus and direct it into position.\n\nFrom there, the fate of this war must rest upon your shoulders.", progress = "Time is precious, now more than ever.", completion = "The way is open. The eternal battlefields of Maldraxxus await you.", objectives = "Activate the gateway to Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61109] = { id = 61109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Hunt-Captain Korayn", description = "I am a Captain of the Wild Hunt, a defender of the sacred groves. As much as I would enjoy the diversion, my place is here fighting back the forces of the enemy, not venturing outside of Ardenweald.\n\nEggs are hatching again at Gormhive and we shall soon be overrun by gormling larva. Until that threat is neutralized I cannot leave my post.", completion = "Well done. Thank you for the help.", objectives = "Remove the threat of Gormhive by smashing eggs, eliminating egg tenders, and slaying gorm so Hunt-Captain Korayn can attend the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61112] = { id = 61112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunger for Flesh", description = "<The bile-soaked cloth bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable.\n\nCommander Gregor will want to know of this at once.>", completion = "This... This is from one of our own... from within the city walls.\n\nI will send word to our patrols. Remain alert, {name}.\n\nShould the Scourge rise up from within our own ranks, find me at once!", objectives = "Bring the Partially Digested Cloth to Commander Gregor in the Trade District of Stormwind City.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61113] = { id = 61113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kivarr's Den", description = "Kivarr... I have not heard that name in many an age.\n\nShe used to make her home near Eventide Grove to the south. Ara'lon knows the area well. I suggest you take him with you.\n\nI fear that the situation with Gweyir weighs heavily upon him. Perhaps joining you on the hunt will do him some good.", progress = "Kivarr has made her home in Ardenweald for many an age, but she has always kept to herself.", completion = "This is the place, but Kivarr is nowhere to be found...", objectives = "Travel to Kivarr's Den at Eventide Grove in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61114] = { id = 61114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunger for Flesh", description = "<The bile-soaked leather bears a deathly odor. Upon closer inspection, it appears familiar. The insignia of the Argent Crusade is unmistakable.\n\nCommander Throgg will want to know of this at once.>", completion = "This... This is from one of our own... from within the city walls.\n\nI will send word to our patrols. Remain alert, {name}.\n\nShould the Scourge rise from within our own ranks, find me at once!", objectives = "Bring the Partially Digested Leather to Commander Throgg in the Valley of Strength in Orgrimmar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61123] = { id = 61123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Polemarch Adrestes", description = "I must politely decline your Prince's offer.\n\nMy skills are needed here, and I am not particularly well-suited to the social demands of attending court.\n\nPerhaps the Paragon of Humility would be a better representative for Bastion.\n\nYou may find him at the Temple of Humility, east of here.\n\nPlease express my sincere regrets that I am unable to attend.", progress = "My answer has not changed.", completion = "Thank you for the reminder that sometimes duty calls me to do things that I find uncomfortable.\n\n<Polemarch Adrestes salutes you.>", objectives = "Seek the assistance of the Paragon of Humility.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61124] = { id = 61124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warren Mongrel" }
quests[61125] = { id = 61125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malevolent Stygia" }
quests[61129] = { id = 61129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Droman Aliothe", description = "I serve my Queen and abide by my oath to guard this hollow and tend the spirits it encloses. \n\nOnce, I might have enjoyed your Prince's party, but I am no longer suited to revelry.\n\nMy world was destroyed long ago, and perhaps I have lost the joy I felt as its wild guardian. I would dearly like a reminder of my old home.\n\nI have heard those strange traders, the brokers, have unusual objects from other worlds. \n\nPerhaps they have something from mine?", progress = "Have you found a reminder of my home for me?", completion = "That scent! I would know it anywhere. My den was surrounded by this plant! Thank you. I will keep this token close to me to remember the joyous times.", objectives = "Investigate the offers of the Brokers to see whether a remnant of Aliothe's world may be found.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61130] = { id = 61130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Sika", description = "Hello, {name}! Sika like to help. So much to do.\n\nWould go to Ember Court, but too many things only Sika can do. Very sorry.", progress = "Busy, busy. Too busy. No one else can do all the things.", completion = "What's in notes? Others need more help from Sika?\n\n<Sika takes in a deep breath.>\n\nSika can do. Sika always helps.", objectives = "Find others in Olympic Village to take on Sika's tasks so she can attend the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61135] = { id = 61135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Crest", description = "With this greatest of gifts from Ardenweald, we have the final piece to rebuild the Crest of Ascension.\n\nLet us make certain Willowblossom's sacrifice is not in vain.", progress = "<The vessel seems drawn to the spot.>", completion = "<Willowblossom's essence will suffuse the crest, completing it so Bastion can once more invest new Ascended.>", objectives = "Place the Vessel of Ardenweald at the Crest of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61136] = { id = 61136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agonix" }
quests[61139] = { id = 61139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Choofa", description = "Oooh a party! I love parties.\n\nMy friends have to come too or it's just not as much fun. Ask them please! You need to find Awool, Rury, and Slanknen so we can go together.", progress = "Friends all ready?", completion = "Hooray! We are going to a party.", objectives = "Make sure all of Choofa's friends are able to attend the party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61140] = { id = 61140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dath Rezara" }
quests[61141] = { id = 61141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathfang's Favorite Toy" }
quests[61143] = { id = 61143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Den", description = "There may be a way to break the curse and free your friend's mind, but it will require some work.\n\nUlfar was wise to send you to me. He knew that a portion of Gorak Tul's power would be necessary, but the other reagents we need do not exist on Azeroth.\n\nMy den is not far from here. Meet me there and I will help you prepare a ritual to break the curse.", completion = "It feels good to be out of that cage and back home in my den.", objectives = "Meet with Kivarr at her den in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61145] = { id = 61145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take The Fight To Them", description = "Our scouts report that Margrave Gharmal gathers their forces at the House of Constructs.\n\nOur necropolis and our new kyrian allies have already begun an aerial assault. I need you to lead our forces on the ground.\n\nMeet me within Zerekriss. We will begin our attack immediately.", completion = "Victory will be ours.", objectives = "Take the portal to meet Draka aboard the Zerekriss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61146] = { id = 61146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manifesting Power", description = "As you know, shedding our memories of life can result in dangerous creatures known as manifestations. They have increased in number and strength as of late, but I believe we can find use for them yet.\n\nManifestations carry great power within them--power we may purify and use in our own creations at the forge here. In making something positive out of such negativity, we do a noble act of service.\n\nSimply eliminate any you come across, and collect their essence. That is all.", progress = "Be cautious in your travels. Manifestations are no simple foe.", completion = "These will do quite nicely! Go in service, Maw Walker.", objectives = "Collect 15 Condensed Essence from manifestations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61148] = { id = 61148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AHHH! Real Monsters!" }
quests[61156] = { id = 61156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There's a Quill...", description = "In times long past, Aspirants trained against the fauna of Bastion. The creation of the Centurions rendered such unstructured progression obsolete.\n\nThe many flying denizens of this realm are known for their quills. They are light and sturdy, perfect for our purposes.\n\nGather all that you can, please. Any flying creature shall suffice.", progress = "Have you the quills?", completion = "Acceptable portion received. You have my thanks.", objectives = "Collect 30 Shimmerflight Quills from flying beasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61157] = { id = 61157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straight to the Point", description = "The horned beasts of Bastion were once commonly used in aspirant training, but centurion sparring units have mostly taken their place. Over the past few eons, their numbers have grown and now must be culled.\n\nTheir horns are critical components to our work. Many specimens are broken from use in battle--they will not suffice. You must be careful in collecting them.\n\nFace them, defeat them, and bring back their horns.", progress = "We require as many horns as you are able to procure.", completion = "Acceptable quality and quantity level. Thank you.", objectives = "Collect 12 Elysian Horns from horned beasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61159] = { id = 61159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Demise", description = "All members of the Forsworn carry an insignia on their person at all times. We suspect they are imbued with the power of the Temple of Loyalty, bolstering their strength against us.\n\nCollect these insignias from their deceased forms. Strip them of this power, and we shall put it to better use in our own machinations.\n\nSuch is the Archon's will, as it is ours.", progress = "Each insignia is a shift of power in our favor.", completion = "These will prove most useful. Well done.", objectives = "Collect 20 Forsworn Insignias from Forsworn kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61161] = { id = 61161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Crashers!" }
quests[61162] = { id = 61162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Crashers!" }
quests[61163] = { id = 61163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Crashers!" }
quests[61164] = { id = 61164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Crashers!" }
quests[61166] = { id = 61166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reduce, Reuse, Recycle", description = "Centurions need lots of parts. But so do we!\n\nKofi needs their metal. Can be from Centurions or the ground. Your choice!\n\nNot too damaged, ok? Hard to clean!", progress = "You have metal?", completion = "This is HEAVY metal! Just like Kofi's favorite music!", objectives = "Collect 20 Resonant Alloy from Forsworn centurions or Centurion parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61171] = { id = 61171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbroken Bonds", description = "The Drust will pay for this foul curse that they've unleashed upon us.\n\nWe have lost too many allies... too many friends to give up now. Even though we cannot save those who have fallen into possession, we can end their torment. I will instruct the hunt to put down all possessed they encounter.\n\nPlease deliver this report to the Winter Queen. She must be told what we have learned.\n\nThank you for your service, {name}. You are a true friend and guardian of Ardenweald.", progress = "What news do you bring?", completion = "If the Thornspeakers have no way to break the curse, then perhaps there truly is no hope for the possessed. These are tidings most dire.", objectives = "Deliver Lord Herne's report to the Winter Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61173] = { id = 61173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Mikanikos", description = "Ember Court sounds interesting ... but very busy right now! Forsworn got into my supplies. Now everything jumbled and disorganized. Can't work in these conditions. My workshop isn't right!\n\nHelp me! Get parts. Most will be damaged and you don't know how to tell about flaws. Bring me many to examine. I will find perfect part.", progress = "Have my parts?", completion = "Perfect one here! See? Rest are bad for my construction. You keep.", objectives = "Assist Mikanikos by gathering potentially perfect parts so he can finish his construction and attend the Ember Court.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61174] = { id = 61174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Baroness Vashj", progress = "Where are the heads of your enemies?", completion = "<Baroness Vashj nods approvingly at the display of heads you placed before her.>\n\nWith your power behind the Prince's efforts, I suppose that I had better pay attention.\n\nVery well. I will pay a visit to Prince Renathal and attend his Ember Court.", objectives = "Gather the heads of fearsome foes to present to Baroness Vashj.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61179] = { id = 61179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forge Ahead", description = "The Eternal Forge has anima again?\n\nAh! Yes! So exciting!\n\nYou must go. Find Forgelite Selene. She will help! So much to make!", completion = "Beautiful, is it not? I was not sure if I would ever see the forge empowered so ever again.", objectives = "Speak to Forgelite Selene at the Eternal Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61180] = { id = 61180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Before Reading", description = "The scroll you recovered details all manner of horrific ways to 'integrate' fallen kyrian into Gharmal's constructs.\n\nIt is also incomplete. There must be more of these among Stitchflesh's remaining followers.\n\nI saw a number of surgeons and their lackeys retreat into the Hall of Chains just ahead as we arrived. I suspect they hold more of these scrolls.\n\nWe must ensure they are never read again.", progress = "This foul work must be destroyed.", completion = "Well done. I will see that these are destroyed personally.", objectives = "Collect 6 Stitchflesh Designs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61182] = { id = 61182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen Your Weight", description = "You know Twirlpetal flowers?! They spin around in the light!\n\nWe need pollen. Only pollen if in bloom!\n\nGet a bunch! Flowers in golden fields. And they spin! Round and round!", progress = "Pollen very fragile. Won't last long!", completion = "So much! Yes, yes, great! Perfect!", objectives = "Collect 30 Twirlpetal Pollen in Bastion's plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61189] = { id = 61189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Gelatinous Research" }
quests[61190] = { id = 61190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wake of Ashes", description = "It feels as if the Maw itself is sentient... and taking notice of our presence.\n\nWe must leave at once. Bolvar must be informed of what is happening here.\n\nI will bring my father with us. Lead the way out of here, {name}. With haste.", completion = "Now to get you and your... associates out of here.", objectives = "Escape from the Maw and report to Bolvar in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61193] = { id = 61193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light Touch", description = "Need Firstborne's Light! You know?\n\nNamed after Archon! Always in water. Kofi's favorite!\n\nShine big light when grown. And go to shore! Easy to see!", progress = "Only grown flowers! Little ones won't work.", completion = "SO SHINY! Kofi need shades next time!", objectives = "Collect 15 Firstborne's Light in water sources.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61196] = { id = 61196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret Ingredient", description = "At times, even the most seasoned kyrian may have difficulty meditating. Recently, such problems have become increasingly common.\n\nThere is a special draught crafted from our purest waters that can be used to focus the mind. I believe it may prove useful in our work here as well, perhaps as a catalyst for more potent reactions.\n\nWill you gather some? Move swiftly, for the liquid becomes unstable once removed from our sacred pools.", progress = "Were you able to find the draught?", completion = "I will put test these samples at once! You have my thanks.", objectives = "Collect 10 Ephemeral Draught.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61199] = { id = 61199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms Day", description = "Many battles here. Especially lately!\n\nNow weapons all over. Too many. We can use!\n\nGo to big battle places and grab them. We will use better!", progress = "Careful with the pointy end!", completion = "These are perfect! Thank you-hoo!", objectives = "Collect 20 Blessed Armaments from battlefields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61209] = { id = 61209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Somber Melody", description = "Though we kyrian cease to be should we perish in battle here, there is much power within Bastion itself that can call forth echoes of our former brothers and sisters.\n\nThese memories wander the roads. At times, they take on some purpose they served in their eternity here--crafting goods, guarding our sacred grounds, and the like.\n\nTake my lyre. Its ancient melody will dispel the memories, and in the process charge it with the residual energy of our realm.", completion = "The lyre thrums with power! We shall make good use of it.", objectives = "Dissipate 15 Kyrian memories along the roads of Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61217] = { id = 61217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thela Soulsipper", objectives = "I remember it all! No more shall I be trapped in this place.\n\nAllow me to assist you in your endeavors Maw Walker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61218] = { id = 61218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Dug Gravewell", objectives = "You've done me a solid, so I'll do you one and help ya out.\n\nMe an' me shovel are at your disposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61219] = { id = 61219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nerith Darkwing", objectives = "After my vengeance it appears I am now without purpose.\n\nI would like to join you and bring terror to your enemies Maw Walker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61220] = { id = 61220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AHHH! Real Monsters!" }
quests[61221] = { id = 61221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Stonehuck", objectives = "My Sinstone ain't been gettin' a lot of use lately.\n\nI reckon if I follow ya I might get a chance to put it to good use.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61222] = { id = 61222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kaletar the Mender", objectives = "Thank you for freeing me Maw Walker.\n\nAllow me to repay your kindness by assisting you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61223] = { id = 61223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ayeleth the Deprived", objectives = "More! \n\nLet me drink from your enemies! \n\nUnleash me upon them!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61226] = { id = 61226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extra Limbs", description = "We cannot carry out the baroness's plans alone. What she proposes will require a well-coordinated unit.\n\nThree individuals maintained Nurakkir alongside me. When the necropolis fell, two of my soulbinds fell with it.\n\nThere remains a single soul paired with mine. My sister, Xennir, survived the wreckage--though grief besets her.\n\nMeet with Xennir. Guide her through her trauma, and return when she is ready to rejoin the fight.", completion = "We have suffered so terribly. I must preserve what I still have.", objectives = "Locate and assist Navigator Xennir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61227] = { id = 61227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Other Foot", description = "It is a fool's errand to command a necropolis without someone to repair it and keep it airborne. Nurrakir's mechanic was slain in the crash.\n\nBut opportunity arises in dire times. Vyn has told me of an... altercation among the constructs. One of their own resisted the reckless scavenging of Nurakkir, and was promptly detained for his objections.\n\nFind this individual. An enemy deserter could make for a potential ally.", completion = "So you need a mechanic? Well, you're in luck!", objectives = "Locate Mechanic Ansid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61228] = { id = 61228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dug's Missing Shovel" }
quests[61230] = { id = 61230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outside Influence", description = "It takes a particular kind of magic to pilot a necropolis. The Eyes' helmsman perished with Nurakkir.\n\nBut Baroness Vashj has informed me of a means to acquire a new helmsman.\n\nFollow me to our house's communications beacon. My baroness has taught me a way to summon just the individual we require.\n\nI suspect she will not be pleased at the prospect of serving us. I trust you will encourage her compliance.", completion = "I appreciate your punctuality.", objectives = "Meet with Khaliiq at the House of Eyes' communications pillar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61234] = { id = 61234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonehuck's Sinstone" }
quests[61243] = { id = 61243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thela's Memory Stone" }
quests[61246] = { id = 61246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Chosen", description = "The necropolis is nearly in position. Now is the time to strike!\n\nWe must force Gharmal into the open together. Join me on my roc, and we will unleash your runeblade's power on the juggernauts.\n\nThe Margrave will be unable to ignore their deaths. Once they leave their blighted tower, we can finish them once and for all.", progress = "Every moment the juggernauts remain standing, our position is in jeopardy!", completion = "Such power! Gharmal will have no choice but to face us now.", objectives = "Destroy the Bilebloat Juggernauts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61248] = { id = 61248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaletar's Freedom" }
quests[61252] = { id = 61252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call In a Favor", description = "We will do just as my baroness commands. Let us conjure a helmsman before us... however displeased it might make her.\n\nActivate the beacon and prepare yourself for a fight. The liches regard all Eyes as their enemies, and I am certain your reputation among them does you no favors.", completion = "My baroness's trust in you is well warranted.", objectives = "Summon Helmsman Caliroux and defeat her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61255] = { id = 61255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Alexandros Mograine", description = "It would be an honor to represent Maldraxxus at the Ember Court of Prince Renathal. \n\nBut before I leave my post, I must ensure my comrades will be safe while I am away.\n\nFight your way into the Ossein Foundry and retrieve weapons from our rivals there.\n\nI will have them distributed among the troops while I make ready to depart.", progress = "Have you gotten the weapons yet?", completion = "A strong advantage. We gain additional arms and deprive our foes of the same.", objectives = "Collect 9 Ossein Staves and 3 Ossein Battleaxes from the Ossein Foundry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61256] = { id = 61256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Kleia and Pelagos", description = "Oh, how wonderful! Thank you for the invitation to the Ember Court.\n\nWe were just going to go cleanse ourselves with a meditation. That will be even more necessary if we are to travel soon. Care to join us?", progress = "Have you completed your meditation yet?", completion = "I always find meditation so relaxing and rewarding. Don't you? Now we are better prepared for our journey!", objectives = "Join Kleia and Pelagos in the Meditation chamber and face the memories of your past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61259] = { id = 61259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ayeleth's Hunger" }
quests[61262] = { id = 61262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerith's Vengeance" }
quests[61265] = { id = 61265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Charm of Alacrity", description = "<You have discovered plans for a charm that seems to hasten your soulbinds in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>You will learn:", objectives = "Bring the Blueprint: Charm of Alacrity to Dactylis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61269] = { id = 61269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Charm of Persistence", description = "<You have discovered plans for a charm that encourages your soulbinds to persevere in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Charm of Persistence to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61272] = { id = 61272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Charm of Discord", description = "<You have discovered plans for a charm that seems to damage your soulbinds' enemies in the Path of Ascension.\n\nDactylis should be able to help you with crafting this charm.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Charm of Discord to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61303] = { id = 61303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Raining Sparkles" }
quests[61304] = { id = 61304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Kyrian Smith's Kit", description = "<You have discovered plans for a kit that lets you repair a piece of armor while out adventuring.\n\nDactylis should be able to help you with crafting this kit.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Kyrian Smith's Kit to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61313] = { id = 61313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kythekios", objectives = "I can fight once more! Allow me to test my mettle against your enemies!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61314] = { id = 61314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME - SCS", description = "You'll need a vessel to hold the anima you need to collect, but one that will also allow you to channel said anima.\n\nThere was once such a device ages ago, but as of late they've become much more rare.\n\nIn my travels through the Maw, I have seen one once. It is in the (AREA NAME), held by (CREATURE).\n\nYou'll need luck on your side in order to retrieve it.", objectives = "Obtain the Anima Focuser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61317] = { id = 61317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Teliah", objectives = "This new weapon is lacking one thing, the blood of my enemies! Allow me to rectify that.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61318] = { id = 61318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Telethakas", objectives = "Honor has been satisfied. Now I require a new master to serve. I would like that to be you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61319] = { id = 61319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hala", objectives = "You have returned my sword to me. I am indebted to you Maw Walker. Allow me to assist you further.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61320] = { id = 61320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Molako", objectives = "I cannot thank you enough for my freedom. I would like to help you further in your tasks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61321] = { id = 61321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ispiron", objectives = "I am whole once more. I would be nothing if it were not for you. I shall dedicate my power to your cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61322] = { id = 61322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kythekios' Memory Stone" }
quests[61323] = { id = 61323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See What You've Done", description = "We have gathered what forces we can. I hope it is enough.\n\nWithin the ruins of our necropolis awaits one final challenge. The one leading the salvage effort calls herself Gorgantus.\n\nTo preserve all that remains to us, we must end her. \n\nLead the attack, and the Eyes will join you. We will reclaim our home.", completion = "I shall execute Akarek's will once more.", objectives = "Slay Gorgantus the Gutter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61330] = { id = 61330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teliah's Stolen Spear" }
quests[61331] = { id = 61331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. As long as this is still happening, we need to save as many as possible!\n\nThe Jailer twists the cycle of life and rebirth. This cannot be allowed to continue! We must thwart his plans.\n\nReturn to the Maw and rescue those that you can.", completion = "Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61332] = { id = 61332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw, circumventing the natural order of the Shadowlands.\n\nThe Jailer denies these souls their rightful eternities. Only you, Maw Walker, can set things right.\n\nReturn to the Maw and save all that you can.", completion = "Well done. They have been spared a truly cruel existence.", objectives = "Rescue 5 Souls from the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61333] = { id = 61333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Maw Walker, I'm sure you've seen firsthand the souls that continue to pour into the Maw. \n\nWe must act now to cut off the Jailer's power, denying him as many souls as possible. That power belongs to the Necrolords.\n\nI shall direct your efforts to save these souls, and help find them a place among the armies of Maldraxxus.\n\nReturn to the Maw and rescue those that you can.", completion = "Excellent Maw Walker. Our armies here will grow stronger with each soul you return.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61334] = { id = 61334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return Lost Souls", description = "Souls continue to pour into the Maw. \n\nTheir anima, our very lifeblood of the Shadowlands, is going with those souls to fuel the Jailer. You rescued me from the Maw. I see no reason you cannot pull more souls from that abyss. \n\nBring souls you rescue from the Maw to me and I shall see them put to better use. At least in Revendreth they have a chance of redemption.", completion = "A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear, their fate is better in our hands than the Jailer's.", objectives = "Rescue Souls in the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61335] = { id = 61335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage Against the Cage", description = "You're looking for a mechanic, are you? Look no further!\n\nI've been toiling on a new necropolis for ages. When Nurakkir collapsed, we saw a golden opportunity! We came to salvage parts from the wreckage, but these brutes locked me up when I criticized their methods.\n\nBut now you need help, right? I'm your construct!\n\nYou get me out of here, and you've got yourself a new mechanic!", progress = "Got a way to free me?", completion = "Thanks for the rescue! I owe you one.", objectives = "Free Ansid the Mechanic from his cage using Toc's key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61337] = { id = 61337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Eternal Protector" }
quests[61340] = { id = 61340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telethakas' Revenge" }
quests[61342] = { id = 61342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battles Won Long Ago" }
quests[61343] = { id = 61343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battles Won Long Ago" }
quests[61346] = { id = 61346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cyrixia the Willbreaker" }
quests[61347] = { id = 61347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Molako's Freedom" }
quests[61348] = { id = 61348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hala's Sword" }
quests[61351] = { id = 61351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Sinstone (+Formal)", progress = "<Prince Renathal looks at the Ancient Sinstone you're carrying with great interest.>\n\nNow where did you find that old sinstone?", completion = "I truly appreciate you bringing this sinstone to me, {name}.\n\nIt is almost as old as I am." }
quests[61352] = { id = 61352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Will Be Consumed" }
quests[61353] = { id = 61353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Will Be Consumed" }
quests[61354] = { id = 61354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "RSVP: Lady Moonberry", description = "Of course I will attend, {name}, the Ember Court sounds like a lot of fun! \n\nBut I cannot go without a gift!\n\nHospitality gifts are an important tradition on many worlds and I feel obliged to provide something suitable for my host and fellow guests.\n\n<Lady Moonberry suppresses a smirk.>\n\nNow for reasons that I'm suuuure won't interest you, I'll need a stout but pretty vine, some dangerous but beautiful blossoms, and of course some gorm pheromones.\n\nEasy enough for someone of your prowess.", progress = "Have you found all of the components for my gift?", completion = "This will be funny. Ah, I mean festive.", objectives = "Collect 3 Silverheart Vine Leaves, 9 Blooming Lasher Spurs, and a Gorm Pheromone Gland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61355] = { id = 61355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rule 2: Keep a Low Profile", description = "Though you may wish to depart with your precious souls in tow, we now have additional matters to settle first.\n\nThe Eye of the Jailer is upon you. And that does not bode well for either of us.\n\nTake this device. You will reinforce my wards to ensure he does not take notice of me as well.\n\nThe last thing I need is a loud, inelegant mortal bringing more attention my way. I can't have the Jailer capturing me, after all.\n\nI'm far too valuable.", progress = "Our business is not yet complete. Attend to my wards.", completion = "That should be enough to hide us from the Jailer's sight.\n\nI need you alive. For the time being, at least.\n\nNow, back to business.", objectives = "Reinforce 4 Soul Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61356] = { id = 61356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echthra, Dame of Hatred", progress = "We have made contact with a member of the former House of Eyes in Maldraxxus. She is a powerful marksman who would prove a most worthy adversary for your soulbinds.\n\nShe has requested a special anointment oil used in kyrian ceremonies in return for her memory.", completion = "That should satisfy our contact. Well done." }
quests[61357] = { id = 61357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatred Abated", description = "As agreed, you may take my memory for the trials you seek.\n\nHeed this warning, mortal--even as an echo of my physical form I will attack without hesitation. Expect no mercy, for I will show none.\n\nYou have done me a great service this day. See to your business.", completion = "A worthy acquisition--you did what you must. I will inform Adrestes of this spy network.", objectives = "Capture Echthra's memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61358] = { id = 61358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alderyn and Myn'ir", progress = "The Wild Hunt is made up of trackers and hunters of incredible might who protect Ardenweald from forces that wish to bring ruin to the place of rest.\n\nWe have reached out to a duo that has agreed to lend their memories if you help them take down a troublesome target.", completion = "This spear should be exactly what they need to take down their quarry." }
quests[61359] = { id = 61359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Primus", description = "As a Necrolord, your duty is to defend the Shadowlands. To carry out such service, the Primus grants us his strength.\n\nStand upon the altar of the Primus. Let his power become your own.", progress = "It is a great gift to wield the Primus's power.", completion = "You are a Necrolord, {name}. We stand strong.", objectives = "Kneel before the Primus and receive his power!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61360] = { id = 61360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt's Gratitude", description = "The forests of Ardenweald are safer with your help, envoy of the kyrian.\n\nAs a reward for your aid, we shall allow you to capture our memory. It is an honor to be chosen to help train the mighty warriors of Bastion.\n\nWhenever you are ready.", completion = "The Wild Hunt are incredible hunters. I look forward to seeing what your soulbinds learn.", objectives = "Capture Alderyn and Myn'ir's memories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61361] = { id = 61361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuuminuuru", progress = "The tirnenn of Ardenweald are ancient, mysterious fae with many lessons to teach. While they prefer to avoid conflict and battle, they are powerful foes if crossed.\n\nOne tirnenn has offered themself as a teacher for your soulbinds. Along with their fleet of faeries, they have many nontraditional, yet crucial, lessons to teach you.", completion = "Though their request was quite nonstandard, I am sure this fountain will be exactly what they need." }
quests[61362] = { id = 61362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caretaker of Faeries", description = "Tirnenn and faeries hold many dissimilarities.\n\nWhile tirnenn stand patient and calm, like the trees that grow tall and protect us, faeries dance and dart and declare their desires directly.\n\nDespite these differences, we stand together. Learning, growing, evolving.\n\nWe will help you and yours achieve the same symbiotic serenity.", completion = "It seems you have already learned from the tirnenn. I look forward to seeing what else they have to share!", objectives = "Capture Nuuminuuru's memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61363] = { id = 61363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mad Mortimer", progress = "An alchemist in Maldraxxus swears that his new creation will be revolutionary, but is still missing a key catalyst.\n\nIf we lend him aid, he has agreed to allow you to capture his memory for the Path.", completion = "<Dactylis inspects the catalyst.>\n\nWell crafted. This should work perfectly for the scientist's needs." }
quests[61364] = { id = 61364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oozing with Opportunity", description = "They called me mad! As a matter of fact, they still do!\n\nAh, but none of them have the mental acuity of Doctor James Mortimus of the very much in-tact House of Plagues, nor his handsome smile! Fools!\n\nWith the catalyst you have so kindly provided, dear...whatever you are...certainly not a kyrian...\n\nI digress!\n\nWe shall get to whatever it is you wanted in a moment, for now is the time of SCIENCE! Come, come, let me show you the wondrous fruits of my labors!", completion = "It appears you were successful. Well done, as always.", objectives = "Aid Mad Mortimer in his experiment, then capture his memory using the Soul Mirror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61365] = { id = 61365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splinterbark Nightmare", progress = "Drust ritualists have created a horrific creature that threatens our nearby allies in Ardenweald.\n\nIf we can successfully clear a path to the creature and mark it with a Praetor Resonance Beacon, we can both capture its essence for the Path and ensure it does not bring harm to the fae realm.", completion = "May a great blow be struck to the drust this day." }
quests[61366] = { id = 61366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Operation", description = "Your target lies near the Oaken Assembly in Ardenweald on the Elder Strand. Take caution, for powerful drust forces lurk nearby.\n\nOnce your target is in sight, activate the beacon and protect the praetors that arrive as they work to subdue the beast. You will only be able to capture its memory once it has been fully incapacitated.\n\nMake haste, and good luck. Follow the path.", completion = "The Nightmare's memory will prove a formidable opponent. May its physical form remain at rest.", objectives = "Activate the Praetor Resonance Beacon at the Splinterbark Nightmare at the Elder Strand in Ardenweald, protect the praetors, then capture the Splinterbark Nightmare's memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61367] = { id = 61367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thran'tiok", progress = "Maldraxxus is home to one of the most powerful types of anima wielders in the Shadowlands, the liches of the House of Rituals. \n\nTraining against a lich would teach your soulbinds important lessons and tactics they can wield if they ever come face to face with a magic user with ill intent.", completion = "This crystal will be useful in finding and capturing the memory you seek." }
quests[61368] = { id = 61368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filching Phylacteries", description = "This phylactery holds the soul of Thran'tiok... her very essence.\n\nBe quick in whatever you need to do. I must get this piece of her soul away from here before she returns.\n\nHer paranoia shall truly be her end.", completion = "It is fortunate that you were able to capture the lich's memory without encountering her herself.\n\nSuch a powerful being is not to be underestimated.", objectives = "Capture Thran'tiok's memory through the Phylactery of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61369] = { id = 61369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craven Corinth", progress = "One of Denathrius's former subjects, Craven Corinth, has been deemed too dangerous to roam free even in their light-bathed Ember Ward.\n\nHis memory would be a perfect opponent in the coliseum. All we need is a key to free him from his prison.", completion = "I am pleased that I retained the designs for this venthyr key for all those millenia. It was not easy to come by." }
quests[61370] = { id = 61370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Other Way", description = "Corinth will not surrender his memory willingly. You must weaken him sufficiently before he will relent to the soul mirror's energy.\n\nYou will find him deep within the Desiccation in Revendreth, locked away among the other light-scarred venthyr. Once you free him, he will surely attack in his confused rage.\n\nSubdue him, and capture his memory. He may then roam free among his kind.", completion = "Another worthy acquisition. Corinth will be a worthy test of your skills.", objectives = "Subdue Craven Corinth in the Desiccation in Revendreth, then capture his memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61371] = { id = 61371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Athanos", progress = "For your final test in the Path, you must face an old friend from your first moments in this realm--Athanos.\n\nIt has been many millenia since the mighty goliath stepped into the arena with his legendary spear, Humility's Guard. The blade was disassembled upon his departure, as is tradition.\n\nShould Athanos bear witness to Humility's Guard once more, I believe he can be convinced to enter the arena once more. We have the shattered spear, but require materials to reforge it.", completion = "May Athanos' return be upon us at last." }
quests[61372] = { id = 61372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Him", description = "Even with Humility's Guard in hand, if you are to convince Athanos to join the Path of Ascension once more then you must prove yourself a worthy adversary.\n\nEnter the ring and wield the spear against him. Even with its power you cannot hope to defeat him, but it should be able to parry his mighty stomp.\n\nThwart his assault for long enough, and he will surely allow you to capture his memory.", completion = "<Dactylis' face expresses what appears to be surprise.>\n\nYou actually did it? Very well! A most worthy opponent indeed.", objectives = "Block Athanos' Power Stomp 6 times, then capture his memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61373] = { id = 61373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azaruux, the Realm Ender", description = "You must act at once!\n\nA devourer of incredible strength has opened a rift in the coliseum and even now threatens to consume it! What few fighters were present at the time struggle to keep the creature at bay.\n\nIf this horror is not stopped, it will continue into the rest of the spires. You must take what anima you can in the area and subdue it.\n\nOnce the threat has been negated, take this spare mirror and capture its memory so we may learn more of its kind for future encounters.", progress = "You must not delay!", completion = "A heroic effort! We will learn much from battling its kind.", objectives = "Absorb anima to activate the Anima Confluxes to subdue Azaruux, then capture its memory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61388] = { id = 61388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Journey Made Together", description = "Binding souls is but the first step. \n\nOver time, the power of our bond will grow in strength and manifest itself in the form of amazing new abilities!\n\nTo tap into this newfound strength, all you must do is place your hand upon the Forge of Bonds. There is no price to pay--the only limitation is your connection to Necrolords.", progress = "This device is merely a conduit to the strength that lies within us both.", completion = "May we prove worthy allies for the battles to come.", objectives = "Activate a Soulbind Power using the Forge of Bonds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61391] = { id = 61391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of the Jailer", description = "<The air around you stands still. A chill of domination suffuses your being. You hear a voice.>\n\nYes... I remember you...\n\nDo you think that because you evaded my grasp once, that I would let it happen again?\n\nNo. The Maw answers to me. All that befalls you here will be because I willed it so.\n\nDeath comes for you, mortal. Everywhere you go, my eye is upon you.You will learn:", sourceObjective = "Speak with Ve'nari about what you just heard.", sourceObjectiveStatus = "unverified-source-field" }
quests[61394] = { id = 61394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormling Toss: Tranquil Pools" }
quests[61395] = { id = 61395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts" }
quests[61396] = { id = 61396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Developments", description = "<The torn document appears to have been written by Surgeon Stitchflesh.>\n\n...the kyrian flesh improves strength, obedience, and dexterity twofold! Such potential!\n\nNow, if subject number one-three-five succeeds in a proper wing transplant at last...\n\n<It continues on for some time. You should bring this to your kyrian allies.>", completion = "Allow me to read this for a moment.", objectives = "Bring the Abhorrent Design to Artemede.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61397] = { id = 61397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opportunity Strikes", description = "This sanctum cannot function on anima alone. It will take many willing souls working in harmony to unlock the full potential of the Seat of the Primus.\n\nOur Soul Warden is always in search of new souls to induct into the sanctum. Your ability to travel back and forth from the Maw will undoubtedly prove useful to him.\n\nYou should pay him a visit to see what assistance you can offer.", completion = "With your unique abilities, we have an opportunity we've never had before.", objectives = "Speak to Osbourne Black.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61398] = { id = 61398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Traditional", description = "Of course Darkhaven is honored to provide traditional decorations for Prince Renathal's court.\n\nVenthyr decor is all about setting a certain mood. That means lurking stonefiends and death blossom scented candles in vast quantity.\n\nOur resources are stretched thin, {name}. We can supply stonefiends easily, but our artisans need wax to melt with fresh death blossom. There should be candle remnants and drips in the village to scrape up. Death blossoms can be harvested from the plants themselves.", progress = "Have you managed to gather the raw materials for our artisans yet?", completion = "We had best get to work right away. Thank you.", objectives = "Collect 50 Candle Wax and 20 Death Blossoms. Death Blossoms can be harvested with the herbalism skill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61399] = { id = 61399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Mortal Reminders", description = "For a reasonable renumeration, Ta Cartel can supply the decorations you require. \n\nRestocking unique and intriguing items is an important aspect of doing business. As you can freely return to your own world, you can provide me some new and exciting products to offer.\n\nYour world has captured the imagination of many of our clients. I have buyers looking for some specific things native to Azeroth.", progress = "Have you found something that fits each item on the list?", completion = "Yes, yes, this is excellent work. Our clients will love these.", objectives = "Help Keeper Ta'saran replenish stock by retrieving the items on the list he's provided you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61400] = { id = 61400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Mystery Mirrors", description = "I support Prince Renathal's efforts and will certainly help the Ember Court!\n\nMystery mirrors will be dangerous but add real excitement to the party. I will need a lot of mirror fragments to complete enough of them in time.\n\nYou will also need to refresh my supply of Ashen Cores so I can get the glass sufficiently molten to work.", progress = "Have you found the mirror fragments and an Ashen Core?", completion = "Thank you for collecting the necessary ingredients to make the mirrors.", objectives = "Collect 12 Shrouded Mirror Shards, 12 Scorched Mirror Fragments, and 3 Molten Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61401] = { id = 61401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Venthyr Volunteers", description = "Oh, hello again!\n\nDid you hear that I have been given command of the guard for the Ember Court? That would probably be more impressive if there were already recruits.\n\nI need to get these recruiting posters up. If you can take care of that, I can meet the interested recruits here and then we can test their combat skills when you return.", progress = "Those posters need to be put in visible locations and the recruits need to be tested.", completion = "Hah! I anticipate some fun with this. I will test the remaining recruits!", objectives = "Place 6 Recruiting Posters and test 3 Sinfall Recruits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[61402] = { id = 61402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ember Court: Stoneborn Reserves", description = "To call up the reserves to provide security for the Ember Court we will need anima. Good, loyal troops are ready as soon as we can animate them.\n\nWe will also need weapons for them.\n\nSort that out and I will make sure the Prince and his guests are well protected.", progress = "Have you filled the anima canister and found enough weapons to equip our new comrades?", completion = "Good. This will be sufficient for me to get those reserves ready.", objectives = "Fill the anima canister by defeating enemy stoneborn in Dominance Keep. Collect 12 Stoneborn Glaives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
